<template><section v-if="data.enrolled" class="migration-card" aria-label="Welcome to AuricWell"><p class="eyebrow">Welcome to AuricWell</p><h2>Settle into your new portal</h2><p>We’re bringing your account over with your care team. More information will appear as it becomes available.</p><p v-if="error" role="alert">{{ error }}</p><ol><li v-for="item in data.items" :key="item.key"><span class="status" :aria-label="item.complete?'Completed':'Next step'">{{ item.complete?'✓':'○' }}</span><div><strong>{{ item.title }}</strong><p>{{ item.detail }}</p><button v-if="!item.complete" @click="$emit('navigate',item.panel)">{{ item.waiting?'View available information':'Review' }}</button><label v-if="item.key==='information'&&!item.complete"><input v-model="confirmed" type="checkbox"> I reviewed this profile and its information is correct.</label><button v-if="item.key==='information'&&!item.complete" :disabled="!confirmed||busy" @click="confirm">Confirm information</button></div></li></ol><p class="history">{{ data.historyNotice }}</p></section><p v-else-if="error" role="alert">{{ error }}</p></template>
<script setup>
import {ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({agencyId:[Number,String],clientId:[Number,String]});defineEmits(['navigate']);const data=ref({}),error=ref(''),confirmed=ref(false),busy=ref(false);let sequence=0;
async function load(){const own=++sequence;data.value={};error.value='';confirmed.value=false;if(!props.agencyId||!props.clientId)return;try{const r=await api.get(`/portal-migration/clients/${props.clientId}`,{params:{agencyId:props.agencyId}});if(own===sequence)data.value=r.data;}catch(e){if(own===sequence)error.value=e.response?.data?.error?.message||'Your onboarding checklist could not be loaded.';}}
async function confirm(){if(busy.value)return;busy.value=true;error.value='';const own=sequence;try{await api.post(`/portal-migration/clients/${props.clientId}/information`,{agencyId:props.agencyId,confirmed:confirmed.value,revision:data.value.informationRevision});if(own===sequence)await load();}catch(e){if(own===sequence)error.value=e.response?.data?.error?.message||'Information could not be confirmed.';}finally{busy.value=false;}}
watch(()=>[props.agencyId,props.clientId],load,{immediate:true});
</script>
<style scoped>.migration-card{padding:24px;border:1px solid #d6e3ef;border-top:4px solid #2467a7;border-radius:14px;background:var(--bg-card,#fff);margin-bottom:24px}.eyebrow{color:#2467a7;font-size:12px;text-transform:uppercase;letter-spacing:.1em}.migration-card h2{margin:8px 0}.migration-card ol{list-style:none;padding:0;margin:20px 0;display:grid;gap:18px}.migration-card li{display:flex;gap:14px;padding-bottom:16px;border-bottom:1px solid #e6edf3}.status{color:#2467a7;font-size:22px}.migration-card p{line-height:1.6}.migration-card button{padding:10px 16px;background:#edf5fb;color:#17436f;border:1px solid #bed2e4;border-radius:8px;cursor:pointer}.migration-card label{display:block;margin:14px 0}.history{font-size:13px;color:#627187}</style>
